/* ============================================================================
   DASH_TABLERO_1  (29/10/2026)  marca DASH_TAB_V1
   ----------------------------------------------------------------------------
   dbo.VCT_MAIN_DASHBOARD: el Inicio del consultor pasa a ser el Tablero de control (boceto v3).
   - Indicadores del mes: capacidad (dias disponibles x 8), asignadas / ejecutadas / programadas en visitas,
     desarrollo registrado / programado, horas sin detallar; proyectos, visitas y acciones a su cargo.
   - Cards: Para hacer (+ Proximas visitas y Horas sin detallar), Mis proyectos, Calendario (Dia / Semana / Mes / Lista).
   - Graficos (boton Tablero | Graficos) y Personalizar (orden y cards ocultas, en el navegador).
   - Solo lectura: los botones abren la V360 del proyecto en la pestania que corresponde.
   - Corrige los textos de los graficos del resto de los perfiles (d&iacute;as / M&aacute;s / ejecuci&oacute;n).
   Assets nuevos: css/vct-tablero.css ?v=1 y js/vct-tablero.js ?v=1 (subir los dos).
   SSMS: F5. Re-ejecutable. Si algun punto no se encuentra, el SP no cambia.
   ============================================================================ */
USE [MuhlePROD];
SET NOCOUNT ON;
GO
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_DASHBOARD')), @NE NVARCHAR(MAX), @RE NVARCHAR(MAX), @i INT, @F NVARCHAR(MAX) = N'', @s INT, @p INT;
IF @D IS NULL
    PRINT 'FALLO: no se encontro dbo.VCT_MAIN_DASHBOARD.';
ELSE IF CHARINDEX(N'DASH_TAB_V1', @D) > 0
    PRINT 'OK   el parche DASH_TAB_V1 ya estaba aplicado: no se hizo nada.';
ELSE IF CHARINDEX(N'DASH_CONSULTOR_V1', @D) = 0
    PRINT 'FALLO: el Inicio del servidor no es el esperado (falta DASH_CONSULTOR_V1). No se cambio nada.';
ELSE
BEGIN
    SET @D = REPLACE(@D, NCHAR(13) + NCHAR(10), NCHAR(10));
    /* tab_block */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'        ORDER BY SUM(V.HEJEC) DESC;' + NCHAR(10) + N'    END;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'        ORDER BY SUM(V.HEJEC) DESC;' + NCHAR(10) + N'    END;' + NCHAR(10) + NCHAR(10) + N'    /* ===================================================================' + NCHAR(10) + N'       TABLERO DE CONTROL DEL CONSULTOR - DASH_TAB_V1' + NCHAR(10) + N'       El Inicio del consultor abre en el tablero (boceto v3): horas del mes contra su capacidad, acciones a su' + NCHAR(10) + N'       cargo, Para hacer, Mis proyectos, calendario combinado y graficos. Solo lectura: las acciones abren la V360.' + NCHAR(10) + N'       Los datos viajan en <textarea data-vt> (una fila por renglon, campos con TAB); los arma js/vct-tablero.js.' + NCHAR(10) + N'       Capacidad: dias DISPONIBLE de VCT_PRM_AGENDA_CONSULTOR x HORAS_CAPACIDAD. Horas de visita por dia:' + NCHAR(10) + N'       VCT_FN_AGENDA_CONSULTOR_RANGO (registradas si hay registro; si no, planificadas, por dia).' + NCHAR(10) + N'       =================================================================== */' + NCHAR(10) + N'    DECLARE @TB_HTML VARCHAR(MAX) = '''';' + NCHAR(10) + N'    IF @VISTA = ''CONSULTOR'' AND @CONS_ID IS NOT NULL' + NCHAR(10) + N'    BEGIN' + NCHAR(10) + N'        DECLARE @TB_MF DATE = DATEADD(DAY, -1, DATEADD(MONTH, 1, @MES_INI)), @TB_DES DATE, @TB_HAS DATE,' + NCHAR(10) + N'                @TB_T CHAR(1) = CHAR(9), @TB_N CHAR(1) = CHAR(10), @TB_MESL VARCHAR(40),' + NCHAR(10) + N'                @TB_KPI VARCHAR(MAX) = '''', @TB_ACC VARCHAR(MAX) = '''', @TB_VIS VARCHAR(MAX) = '''', @TB_DIA VARCHAR(MAX) = '''',' + NCHAR(10) + N'                @TB_DEV VARCHAR(MAX) = '''', @TB_PRO VARCHAR(MAX) = '''', @TB_MES VARCHAR(MAX) = '''';' + NCHAR(10) + N'        SET @TB_DES = CASE WHEN DATEADD(DAY, -42, @HOY) < @MES_INI THEN DATEADD(DAY, -42, @HOY) ELSE @MES_INI END;' + NCHAR(10) + N'        SET @TB_HAS = CASE WHEN DATEADD(DAY, 56, @HOY) > @TB_MF THEN DATEADD(DAY, 56, @HOY) ELSE @TB_MF END;' + NCHAR(10) + N'        SET @TB_MESL = CASE MONTH(@HOY) WHEN 1 THEN ''enero'' WHEN 2 THEN ''febrero'' WHEN 3 THEN ''marzo'' WHEN 4 THEN ''abril'' WHEN 5 THEN ''mayo'' WHEN 6 THEN ''junio''' + NCHAR(10) + N'                            WHEN 7 THEN ''julio'' WHEN 8 THEN ''agosto'' WHEN 9 THEN ''septiembre'' WHEN 10 THEN ''octubre'' WHEN 11 THEN ''noviembre'' ELSE ''diciembre'' END' + NCHAR(10) + N'                     + '' '' + CONVERT(VARCHAR(4), YEAR(@HOY));' + NCHAR(10) + NCHAR(10) + N'        /* agenda por dia (6 meses hacia atras hasta 8 semanas adelante) */' + NCHAR(10) + N'        CREATE TABLE #TBD (FECHA DATE PRIMARY KEY, EST VARCHAR(30), HORAS DECIMAL(9,2), TIPO VARCHAR(20), CAP DECIMAL(9,2), FER BIT, HAB BIT);' + NCHAR(10) + N'        INSERT INTO #TBD (FECHA, EST, HORAS, TIPO, CAP, FER, HAB)' + NCHAR(10) + N'        SELECT R.FECHA, ISNULL(R.ESTADO, ''''), ISNULL(R.HORAS, 0), AG.TIPO, ISNULL(AG.HORAS_CAPACIDAD, 8),' + NCHAR(10) + N'               CASE WHEN ISNULL(CL.IsHoliday, 0) = 1 THEN 1 ELSE 0 END,' + NCHAR(10) + N'               CASE WHEN DATEDIFF(DAY, ''19000101'', R.FECHA) % 7 < 5 AND ISNULL(CL.IsHoliday, 0) = 0 THEN 1 ELSE 0 END' + NCHAR(10) + N'        FROM dbo.VCT_FN_AGENDA_CONSULTOR_RANGO(@CONS_ID, @DESDE6, @TB_HAS) R' + NCHAR(10) + N'        LEFT JOIN dbo.VCT_PRM_AGENDA_CONSULTOR AG WITH(NOLOCK) ON AG.ID_CONSULTOR = @CONS_ID AND AG.FECHA = R.FECHA' + NCHAR(10) + N'        LEFT JOIN dbo.Calendar CL WITH(NOLOCK) ON CL.Fecha = R.FECHA;' + NCHAR(10) + NCHAR(10) + N'        /* mis visitas (12 meses hacia atras y las futuras) con su desarrollo */' + NCHAR(10) + N'        CREATE TABLE #TBV (ID INT PRIMARY KEY, ID_PROYECTO INT, DESDE DATE, HASTA DATE, EST VARCHAR(50), HP DECIMAL(9,2), HE DECIMAL(9,2),' + NCHAR(10) + N'                           DR DECIMAL(9,2), DP DECIMAL(9,2), SINREG BIT, DIAS VARCHAR(2000));' + NCHAR(10) + N'        INSERT INTO #TBV (ID, ID_PROYECTO, DESDE, HASTA, EST, HP, HE, DR, DP, SINREG, DIAS)' + NCHAR(10) + N'        SELECT V.ID, V.ID_PROYECTO, CONVERT(DATE, V.FECHA_DESDE), CONVERT(DATE, ISNULL(V.FECHA_HASTA, V.FECHA_DESDE)), UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO, '''')))),' + NCHAR(10) + N'               ISNULL(VC.HORAS_PLANIFICADAS, 0), ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)), ISNULL(DX.R, 0), ISNULL(DX.P, 0),' + NCHAR(10) + N'               CASE WHEN CONVERT(DATE, V.FECHA_DESDE) BETWEEN DATEADD(DAY, -30, @HOY) AND DATEADD(DAY, -1, @HOY)' + NCHAR(10) + N'                         AND NOT EXISTS (SELECT 1 FROM dbo.VCT_PROYECTOS_VISITAS_REGISTRO RG WITH(NOLOCK) WHERE RG.ID_VISITA = V.ID) THEN 1 ELSE 0 END,' + NCHAR(10) + N'               ISNULL(STUFF((SELECT ''|'' + CONVERT(VARCHAR(10), DD.FECHA, 120) + ''='' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), DD.HORAS)), ''.0'', '''')' + NCHAR(10) + N'                             FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES_DIAS DD WITH(NOLOCK) WHERE DD.ID_VISITA = V.ID AND DD.ID_CONSULTOR = @CONS_ID ORDER BY DD.FECHA' + NCHAR(10) + N'                             FOR XML PATH('''')), 1, 1, ''''), '''')' + NCHAR(10) + N'        FROM dbo.VCT_PROYECTOS_VISITAS V WITH(NOLOCK)' + NCHAR(10) + N'        INNER JOIN dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK) ON VC.ID_VISITA = V.ID AND VC.ID_CONSULTOR = @CONS_ID' + NCHAR(10) + N'        OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN D.HORAS ELSE 0 END) AS R, SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN D.HORAS ELSE 0 END) AS P' + NCHAR(10) + N'                     FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = V.ID AND D.ID_CONSULTOR = @CONS_ID) DX' + NCHAR(10) + N'        WHERE V.FECHA_DESDE >= @DESDE12 AND UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO, '''')))) NOT IN (''CANCELADO'', ''CANCELADA'', ''ANULADO'', ''ANULADA'');' + NCHAR(10) + NCHAR(10) + N'        /* acciones a mi cargo (abiertas y las cerradas desde el mes anterior) */' + NCHAR(10) + N'        CREATE TABLE #TBA (ID INT PRIMARY KEY, ID_PROYECTO INT, ITEM VARCHAR(50), TIT VARCHAR(300), VENCE DATE, EST VARCHAR(100), ESTC VARCHAR(30), FINAL BIT,' + NCHAR(10) + N'                           CIERRE DATE, PRIO VARCHAR(100), PNIV INT, ESPLAN BIT, DN INT, DR DECIMAL(9,2), DP DECIMAL(9,2));' + NCHAR(10) + N'        INSERT INTO #TBA (ID, ID_PROYECTO, ITEM, TIT, VENCE, EST, ESTC, FINAL, CIERRE, PRIO, PNIV, ESPLAN, DN, DR, DP)' + NCHAR(10) + N'        SELECT A.ID, A.ID_PROYECTO, ISNULL(PI.CODIGO_ITEM, ''''), ISNULL(A.TITULO, ''''), CONVERT(DATE, A.FECHA_VENCIMIENTO), ISNULL(E.DESCRIPCION, ''''), ISNULL(E.CODIGO, ''''),' + NCHAR(10) + N'               ISNULL(E.ES_FINAL, 0), CONVERT(DATE, A.FECHA_CIERRE), ISNULL(PR.DESCRIPCION, ''''), ISNULL(PR.NIVEL, 0), CASE WHEN A.ID_PLAN_ITEM IS NULL THEN 0 ELSE 1 END,' + NCHAR(10) + N'               ISNULL(DX.N, 0), ISNULL(DX.R, 0), ISNULL(DX.P, 0)' + NCHAR(10) + N'        FROM dbo.VCT_ACCIONES A WITH(NOLOCK)' + NCHAR(10) + N'        INNER JOIN dbo.VCT_PRM_ACCIONES_ESTADOS E WITH(NOLOCK) ON E.ID = A.ID_ESTADO' + NCHAR(10) + N'        LEFT JOIN dbo.VCT_PRM_ACCIONES_PRIORIDADES PR WITH(NOLOCK) ON PR.ID = A.ID_PRIORIDAD' + NCHAR(10) + N'        LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS PI WITH(NOLOCK) ON PI.ID = A.ID_PLAN_ITEM' + NCHAR(10) + N'        OUTER APPLY (SELECT COUNT(*) AS N, SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN D.HORAS ELSE 0 END) AS R, SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN D.HORAS ELSE 0 END) AS P' + NCHAR(10) + N'                     FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_ACCION = A.ID) DX' + NCHAR(10) + N'        WHERE EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_PARTICIPANTES AP WITH(NOLOCK) WHERE AP.ID_ACCION = A.ID AND AP.ESTADO = ''ACTIVO''' + NCHAR(10) + N'                      AND AP.ROL_PARTICIPANTE = ''RESPONSABLE'' AND AP.TIPO_ENTIDAD = ''CONSULTOR'' AND AP.ID_ENTIDAD = @CONS_ID)' + NCHAR(10) + N'          AND (ISNULL(E.ES_FINAL, 0) = 0 OR A.FECHA_CIERRE >= @MES_ANT);' + NCHAR(10) + NCHAR(10) + N'        /* proyectos: los activos del alcance (#DP) y los que aparecen en mis visitas / acciones */' + NCHAR(10) + N'        CREATE TABLE #TBP (ID INT PRIMARY KEY, ACTIVO BIT);' + NCHAR(10) + N'        INSERT INTO #TBP (ID, ACTIVO) SELECT ID, 1 FROM #DP;' + NCHAR(10) + N'        INSERT INTO #TBP (ID, ACTIVO)' + NCHAR(10) + N'        SELECT X.ID_PROYECTO, 0 FROM (SELECT ID_PROYECTO FROM #TBV UNION SELECT ID_PROYECTO FROM #TBA) X' + NCHAR(10) + N'        WHERE X.ID_PROYECTO IS NOT NULL AND NOT EXISTS (SELECT 1 FROM #TBP T WHERE T.ID = X.ID_PROYECTO);' + NCHAR(10) + NCHAR(10) + N'        /* indicadores */' + NCHAR(10) + N'        DECLARE @K_CAP DECIMAL(9,2), @K_DD INT, @K_HAB INT, @K_LIC DECIMAL(9,2), @K_NC DECIMAL(9,2), @K_EJE DECIMAL(9,2), @K_PRO DECIMAL(9,2),' + NCHAR(10) + N'                @K_DR DECIMAL(9,2), @K_DP DECIMAL(9,2), @K_SD DECIMAL(9,2), @K_SDN INT, @K_VM INT, @K_VH INT, @K_VPX VARCHAR(20);' + NCHAR(10) + N'        SELECT @K_CAP = SUM(CASE WHEN TIPO = ''DISPONIBLE'' THEN CAP ELSE 0 END), @K_DD = SUM(CASE WHEN TIPO = ''DISPONIBLE'' THEN 1 ELSE 0 END),' + NCHAR(10) + N'               @K_HAB = SUM(CASE WHEN HAB = 1 THEN 1 ELSE 0 END), @K_LIC = SUM(CASE WHEN TIPO = ''LICENCIA'' AND HAB = 1 THEN 8 ELSE 0 END),' + NCHAR(10) + N'               @K_NC = SUM(CASE WHEN TIPO IS NULL AND HAB = 1 THEN 8 ELSE 0 END),' + NCHAR(10) + N'               @K_EJE = SUM(CASE WHEN EST = ''ASIGNADO'' AND FECHA <= @HOY THEN HORAS ELSE 0 END), @K_PRO = SUM(CASE WHEN EST = ''ASIGNADO'' AND FECHA > @HOY THEN HORAS ELSE 0 END)' + NCHAR(10) + N'        FROM #TBD WHERE FECHA BETWEEN @MES_INI AND @TB_MF;' + NCHAR(10) + N'        SELECT @K_DR = SUM(DR), @K_DP = SUM(DP), @K_VM = COUNT(*), @K_VH = SUM(CASE WHEN DESDE <= @HOY THEN 1 ELSE 0 END),' + NCHAR(10) + N'               @K_SD = SUM(CASE WHEN DESDE <= @HOY AND HE > DR THEN HE - DR ELSE 0 END), @K_SDN = SUM(CASE WHEN DESDE <= @HOY AND HE > DR THEN 1 ELSE 0 END)' + NCHAR(10) + N'        FROM #TBV WHERE DESDE BETWEEN @MES_INI AND @TB_MF;' + NCHAR(10) + N'        SELECT TOP 1 @K_VPX = LOWER(CASE (DATEDIFF(DAY, ''19000101'', DESDE) % 7) WHEN 0 THEN ''lun'' WHEN 1 THEN ''mar'' WHEN 2 THEN ''mi'' + CHAR(233) WHEN 3 THEN ''jue''' + NCHAR(10) + N'                                     WHEN 4 THEN ''vie'' WHEN 5 THEN ''s'' + CHAR(225) + ''b'' ELSE ''dom'' END) + '' '' + CONVERT(VARCHAR(5), DESDE, 103)' + NCHAR(10) + N'        FROM #TBV WHERE DESDE > @HOY ORDER BY DESDE;' + NCHAR(10) + NCHAR(10) + N'        SET @TB_KPI = CONVERT(VARCHAR(MAX), '''')' + NCHAR(10) + N'            + ''cap'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_CAP, 0))), ''.0'', '''') + @TB_N + ''dd'' + @TB_T + ISNULL(CONVERT(VARCHAR(20), ISNULL(@K_DD, 0)), '''') + @TB_N + ''hab'' + @TB_T + ISNULL(CONVERT(VARCHAR(20), ISNULL(@K_HAB, 0)), '''') + @TB_N + ''lic'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_LIC, 0))), ''.0'', '''') + @TB_N + ''nc'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_NC, 0))), ''.0'', '''') + @TB_N' + NCHAR(10) + N'            + ''eje'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_EJE, 0))), ''.0'', '''') + @TB_N + ''pro'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_PRO, 0))), ''.0'', '''') + @TB_N + ''devr'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_DR, 0))), ''.0'', '''') + @TB_N + ''devp'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_DP, 0))), ''.0'', '''') + @TB_N' + NCHAR(10) + N'            + ''sind'' + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(@K_SD, 0))), ''.0'', '''') + @TB_N + ''sindn'' + @TB_T + ISNULL(CONVERT(VARCHAR(20), ISNULL(@K_SDN, 0)), '''') + @TB_N + ''vmes'' + @TB_T + ISNULL(CONVERT(VARCHAR(20), ISNULL(@K_VM, 0)), '''') + @TB_N + ''vhec'' + @TB_T + ISNULL(CONVERT(VARCHAR(20), ISNULL(@K_VH, 0)), '''') + @TB_N' + NCHAR(10) + N'            + ''vprox'' + @TB_T + ISNULL(@K_VPX, '''') + @TB_N' + NCHAR(10) + N'            + ''np'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #DP)) + @TB_N' + NCHAR(10) + N'            + ''npc'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #DP WHERE EST = ''ENCURSO'')) + @TB_N' + NCHAR(10) + N'            + ''npl'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #DP WHERE EST = ''CONFIRMADO'')) + @TB_N' + NCHAR(10) + N'            + ''aven'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE FINAL = 0 AND VENCE < @HOY)) + @TB_N' + NCHAR(10) + N'            + ''avenp'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(DISTINCT ID_PROYECTO) FROM #TBA WHERE FINAL = 0 AND VENCE < @HOY)) + @TB_N' + NCHAR(10) + N'            + ''ahoy'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE FINAL = 0 AND VENCE = @HOY)) + @TB_N' + NCHAR(10) + N'            + ''asem'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE FINAL = 0 AND VENCE > @HOY AND VENCE <= DATEADD(DAY, 7, @HOY))) + @TB_N' + NCHAR(10) + N'            + ''aabi'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE FINAL = 0)) + @TB_N' + NCHAR(10) + N'            + ''acur'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE FINAL = 0 AND ESTC = ''EN_PROCESO'')) + @TB_N' + NCHAR(10) + N'            + ''asfe'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE FINAL = 0 AND VENCE IS NULL)) + @TB_N' + NCHAR(10) + N'            + ''asdv'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE FINAL = 0 AND ESPLAN = 1 AND DN = 0)) + @TB_N' + NCHAR(10) + N'            + ''cmes'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE ESTC = ''CUMPLIDA'' AND CIERRE >= @MES_INI)) + @TB_N' + NCHAR(10) + N'            + ''cant'' + @TB_T + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM #TBA WHERE ESTC = ''CUMPLIDA'' AND CIERRE >= @MES_ANT AND CIERRE < @MES_INI)) + @TB_N;' + NCHAR(10) + NCHAR(10) + N'        /* acciones: abiertas (las 500 mas proximas) y cerradas de las ultimas 2 semanas (grafico) */' + NCHAR(10) + N'        SET @TB_ACC = ISNULL((SELECT ISNULL(CONVERT(VARCHAR(20), A.ID), '''') + @TB_T + ISNULL(CONVERT(VARCHAR(20), A.ID_PROYECTO), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(50), A.ITEM), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(300), A.TIT), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + ISNULL(CONVERT(VARCHAR(10), A.VENCE, 120), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(100), A.EST), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(30), A.ESTC), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + CONVERT(VARCHAR(1), A.FINAL) + @TB_T + ISNULL(CONVERT(VARCHAR(10), A.CIERRE, 120), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(100), A.PRIO), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + ISNULL(CONVERT(VARCHAR(20), A.PNIV), '''') + @TB_T + CONVERT(VARCHAR(1), A.ESPLAN) + @TB_T + ISNULL(CONVERT(VARCHAR(20), A.DN), '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(A.DR, 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(A.DP, 0))), ''.0'', '''') + @TB_N' + NCHAR(10) + N'            FROM (SELECT * FROM (SELECT TOP 500 * FROM #TBA WHERE FINAL = 0 ORDER BY CASE WHEN VENCE IS NULL THEN 1 ELSE 0 END, VENCE, PNIV DESC) A1' + NCHAR(10) + N'                  UNION ALL SELECT * FROM #TBA WHERE FINAL = 1 AND CIERRE >= DATEADD(DAY, -14, @HOY)) A' + NCHAR(10) + N'            ORDER BY A.FINAL, A.VENCE, A.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'', ''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        /* visitas de la ventana del calendario */' + NCHAR(10) + N'        SET @TB_VIS = ISNULL((SELECT ISNULL(CONVERT(VARCHAR(20), V.ID), '''') + @TB_T + ISNULL(CONVERT(VARCHAR(20), V.ID_PROYECTO), '''') + @TB_T + ISNULL(CONVERT(VARCHAR(10), V.DESDE, 120), '''') + @TB_T + ISNULL(CONVERT(VARCHAR(10), V.HASTA, 120), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(50), V.EST), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(V.HP, 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(V.HE, 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(V.DR, 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(V.DP, 0))), ''.0'', '''') + @TB_T + CONVERT(VARCHAR(1), V.SINREG) + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(2000), V.DIAS), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_N' + NCHAR(10) + N'            FROM #TBV V WHERE V.HASTA >= @TB_DES AND V.DESDE <= @TB_HAS' + NCHAR(10) + N'            ORDER BY V.DESDE, V.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'', ''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        /* agenda por dia de la ventana */' + NCHAR(10) + N'        SET @TB_DIA = ISNULL((SELECT ISNULL(CONVERT(VARCHAR(10), D.FECHA, 120), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(30), D.EST), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(20), D.TIPO), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + CONVERT(VARCHAR(1), D.FER) + @TB_T + CONVERT(VARCHAR(1), D.HAB) + @TB_N' + NCHAR(10) + N'            FROM #TBD D WHERE D.FECHA BETWEEN @TB_DES AND @TB_HAS' + NCHAR(10) + N'            ORDER BY D.FECHA' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'', ''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        /* desarrollo de mis visitas de la ventana */' + NCHAR(10) + N'        SET @TB_DEV = ISNULL((SELECT ISNULL(CONVERT(VARCHAR(10), V.DESDE, 120), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(12), D.TIPO), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + @TB_T + ISNULL(CONVERT(VARCHAR(20), V.ID_PROYECTO), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(50), PI.CODIGO_ITEM), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(300), D.TITULO), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + ISNULL(CONVERT(VARCHAR(20), D.ID_ACCION), '''') + @TB_N' + NCHAR(10) + N'            FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) INNER JOIN #TBV V ON V.ID = D.ID_VISITA' + NCHAR(10) + N'            LEFT JOIN dbo.VCT_ACCIONES A WITH(NOLOCK) ON A.ID = D.ID_ACCION LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS PI WITH(NOLOCK) ON PI.ID = A.ID_PLAN_ITEM' + NCHAR(10) + N'            WHERE D.ID_CONSULTOR = @CONS_ID AND V.DESDE BETWEEN @TB_DES AND @TB_HAS' + NCHAR(10) + N'            ORDER BY V.DESDE, D.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'', ''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        /* proyectos */' + NCHAR(10) + N'        SET @TB_PRO = ISNULL((SELECT ISNULL(CONVERT(VARCHAR(20), T.ID), '''') + @TB_T + ISNULL(CONVERT(VARCHAR(20), P.IDCLIENTE), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(100), P.CODIGO), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(300), P.NOMBRE), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(300), CL.RAZON_SOCIAL), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(30), E.CODIGO), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + ISNULL(CONVERT(VARCHAR(20), ISNULL(P.PORCENTAJE_AVANCE, 0)), '''') + @TB_T + REPLACE(REPLACE(REPLACE(ISNULL(CONVERT(VARCHAR(300), SV.NOM), ''''), CHAR(9), '' ''), CHAR(10), '' ''), CHAR(13), '' '') + @TB_T + ISNULL(CONVERT(VARCHAR(10), CASE WHEN FV.D IS NULL OR P.FECHA_FIN IS NULL OR CONVERT(DATE, P.FECHA_FIN) <= FV.D THEN NULL WHEN @HOY >= CONVERT(DATE, P.FECHA_FIN) THEN 100 WHEN @HOY <= FV.D THEN 0 ELSE CONVERT(INT, ROUND(100.0 * DATEDIFF(DAY, FV.D, @HOY) / DATEDIFF(DAY, FV.D, CONVERT(DATE, P.FECHA_FIN)), 0)) END), '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(HX.E, 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(NULLIF(P.TOTAL_HORAS_PROYECTADAS, 0), 0))), ''.0'', '''') + @TB_T + ISNULL(CONVERT(VARCHAR(10), DATEDIFF(DAY, @HOY, CONVERT(DATE, P.FECHA_FIN))), '''') + @TB_T + CASE WHEN E.CODIGO = ''CONFIRMADO'' THEN ''Lanzamiento'' WHEN EXISTS (SELECT 1 FROM #CA CA WHERE CA.ID_PROYECTO = T.ID AND CA.FINAL = 0 AND CA.SUB = ''CARGA_PLAN'') THEN ''Plan por cargar'' ELSE ''En ejecuci&oacute;n'' END + @TB_T + CONVERT(VARCHAR(1), T.ACTIVO) + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(MV.A, 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(MV.D, 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL(MV.H12, 0))), ''.0'', '''') + @TB_N' + NCHAR(10) + N'            FROM #TBP T INNER JOIN dbo.VCT_PROYECTOS P WITH(NOLOCK) ON P.ID = T.ID' + NCHAR(10) + N'            LEFT JOIN dbo.VCT_PRM_PROYECTOS_ESTADOS E WITH(NOLOCK) ON E.ID = P.ID_ESTADO' + NCHAR(10) + N'            LEFT JOIN dbo.VCT_CLIENTES CL WITH(NOLOCK) ON CL.ID = P.IDCLIENTE' + NCHAR(10) + N'            OUTER APPLY (SELECT TOP 1 ISNULL(NULLIF(LTRIM(RTRIM(PS.NOMBRE)), ''''), S.DESCRIPCION) AS NOM FROM dbo.VCT_PROYECTOS_SERVICIOS PS WITH(NOLOCK)' + NCHAR(10) + N'                         LEFT JOIN dbo.VCT_PRM_SERVICIOS S WITH(NOLOCK) ON S.ID = PS.ID_SERVICIO WHERE PS.ID_PROYECTO = T.ID ORDER BY PS.PRINCIPAL DESC, PS.ORDEN, PS.ID) SV' + NCHAR(10) + N'            OUTER APPLY (SELECT MIN(CONVERT(DATE, V.FECHA_DESDE)) AS D FROM dbo.VCT_PROYECTOS_VISITAS V WITH(NOLOCK)' + NCHAR(10) + N'                         WHERE V.ID_PROYECTO = T.ID AND UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO, '''')))) NOT IN (''CANCELADO'', ''CANCELADA'', ''ANULADO'', ''ANULADA'')) FV' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(V.TOTAL_HORAS_EJECUTADAS) AS E FROM dbo.VCT_PROYECTOS_VISITAS V WITH(NOLOCK) WHERE V.ID_PROYECTO = T.ID AND V.FECHA_DESDE <= GETDATE()) HX' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(CASE WHEN W.DESDE BETWEEN @MES_INI AND @TB_MF THEN W.HP ELSE 0 END) AS A, SUM(CASE WHEN W.DESDE BETWEEN @MES_INI AND @TB_MF THEN W.DR ELSE 0 END) AS D,' + NCHAR(10) + N'                                SUM(CASE WHEN W.DESDE <= @HOY THEN W.HE ELSE 0 END) AS H12 FROM #TBV W WHERE W.ID_PROYECTO = T.ID) MV' + NCHAR(10) + N'            ORDER BY T.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'', ''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        /* ultimos 6 meses */' + NCHAR(10) + N'        SET @TB_MES = ISNULL((SELECT M.LBL + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL((SELECT SUM(CASE WHEN D.EST = ''ASIGNADO'' AND D.FECHA <= @HOY THEN D.HORAS ELSE 0 END) FROM #TBD D WHERE D.FECHA >= M.MES AND D.FECHA < DATEADD(MONTH, 1, M.MES)), 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL((SELECT SUM(CASE WHEN D.EST = ''ASIGNADO'' AND D.FECHA > @HOY THEN D.HORAS ELSE 0 END) FROM #TBD D WHERE D.FECHA >= M.MES AND D.FECHA < DATEADD(MONTH, 1, M.MES)), 0))), ''.0'', '''') + @TB_T + REPLACE(CONVERT(VARCHAR(30), CONVERT(DECIMAL(18,1), ISNULL((SELECT SUM(CASE WHEN D.TIPO = ''DISPONIBLE'' THEN D.CAP ELSE 0 END) FROM #TBD D WHERE D.FECHA >= M.MES AND D.FECHA < DATEADD(MONTH, 1, M.MES)), 0))), ''.0'', '''') + @TB_N' + NCHAR(10) + N'            FROM #DM M WHERE M.MES >= @DESDE6' + NCHAR(10) + N'            ORDER BY M.ORD' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'', ''VARCHAR(MAX)''), '''');' + NCHAR(10) + NCHAR(10) + N'        SET @TB_HTML = CONVERT(VARCHAR(MAX), '''')' + NCHAR(10) + N'            + ''<div class="vtb" data-vtb data-hoy="'' + CONVERT(VARCHAR(10), @HOY, 120) + ''" data-mes="'' + @TB_MESL + ''"''' + NCHAR(10) + N'            + '' data-des="'' + CONVERT(VARCHAR(10), @TB_DES, 120) + ''" data-has="'' + CONVERT(VARCHAR(10), @TB_HAS, 120) + ''" data-guid="'' + @GUID_P + ''"''' + NCHAR(10) + N'            + '' data-user="'' + REPLACE(REPLACE(REPLACE(LOWER(ISNULL(@IAGENTE, '''')), ''&'', ''&amp;''), ''<'', ''&lt;''), ''"'', ''&quot;'') + ''">''' + NCHAR(10) + N'            + ''<textarea hidden data-vt="kpi">'' + REPLACE(REPLACE(REPLACE(@TB_KPI, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</textarea>''' + NCHAR(10) + N'            + ''<textarea hidden data-vt="acc">'' + REPLACE(REPLACE(REPLACE(@TB_ACC, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</textarea>''' + NCHAR(10) + N'            + ''<textarea hidden data-vt="vis">'' + REPLACE(REPLACE(REPLACE(@TB_VIS, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</textarea>''' + NCHAR(10) + N'            + ''<textarea hidden data-vt="dia">'' + REPLACE(REPLACE(REPLACE(@TB_DIA, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</textarea>''' + NCHAR(10) + N'            + ''<textarea hidden data-vt="dev">'' + REPLACE(REPLACE(REPLACE(@TB_DEV, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</textarea>''' + NCHAR(10) + N'            + ''<textarea hidden data-vt="pro">'' + REPLACE(REPLACE(REPLACE(@TB_PRO, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</textarea>''' + NCHAR(10) + N'            + ''<textarea hidden data-vt="mes">'' + REPLACE(REPLACE(REPLACE(@TB_MES, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</textarea>''' + NCHAR(10) + N'            + ''<div data-vtb-root><div class="vtb-loading">Cargando el tablero&hellip;</div></div></div>'';' + NCHAR(10) + N'    END;' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' tab_block'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* tab_out */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'      + @PANELS' + NCHAR(10);
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'      + CASE WHEN ISNULL(@TB_HTML, '''') <> '''' THEN @TB_HTML ELSE @PANELS END   /* DASH_TAB_V1 */' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' tab_out'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* tab_assets */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'      + ''<script src="../js/vct-money.js?v=1"></script>''' + NCHAR(10);
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'      + ''<script src="../js/vct-money.js?v=1"></script>''' + NCHAR(10) + N'      + CASE WHEN ISNULL(@TB_HTML, '''') <> '''' THEN ''<link rel="stylesheet" href="../css/vct-tablero.css?v=1"><script src="../js/vct-tablero.js?v=1"></script>'' ELSE '''' END   /* DASH_TAB_V1 */' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' tab_assets'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* lbl_v */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<span class="vct-dash-vlbl">'' + REPLACE(REPLACE(REPLACE(S.LBL, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</span></div>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ ''<span class="vct-dash-vlbl">'' + REPLACE(REPLACE(S.LBL, ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</span></div>''';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' lbl_v'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* lbl_h */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ REPLACE(REPLACE(REPLACE(S.LBL, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</span>''' + NCHAR(10);
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ REPLACE(REPLACE(S.LBL, ''<'', ''&lt;''), ''>'', ''&gt;'') + ''</span>''' + NCHAR(10);
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' lbl_h'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    /* lbl_d */
    SET @NE = CONVERT(NVARCHAR(MAX), N'') + N'+ REPLACE(REPLACE(REPLACE(S.LBL, ''&'', ''&amp;''), ''<'', ''&lt;''), ''>'', ''&gt;'') + '' <b>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'') + N'+ REPLACE(REPLACE(S.LBL, ''<'', ''&lt;''), ''>'', ''&gt;'') + '' <b>''';
    SET @i = CHARINDEX(@NE, @D);
    IF @i = 0 OR CHARINDEX(@NE, @D, @i + 1) > 0 SET @F = @F + N' lbl_d'; ELSE SET @D = STUFF(@D, @i, LEN(@NE + N'x') - 1, @RE);
    IF @F <> N''
        PRINT 'FALLO: no se encontraron (o estan repetidos) en la definicion vigente los puntos:' + @F + '. No se cambio nada.';
    ELSE
    BEGIN
        SET @s = CHARINDEX(N'PROCEDURE', @D);
        SET @p = CASE WHEN @s > 40 THEN @s - 40 ELSE 1 END;
        IF CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) > 0 AND CHARINDEX(N'OR ALTER', SUBSTRING(@D, @p, 40)) = 0
            SET @D = STUFF(@D, @p + CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) - 1, 6, N'ALTER ');
        BEGIN TRY
            EXEC sys.sp_executesql @D;
            PRINT 'OK   VCT_MAIN_DASHBOARD actualizado (DASH_TAB_V1). Subir css/vct-tablero.css y js/vct-tablero.js.';
        END TRY
        BEGIN CATCH
            PRINT 'FALLO al actualizar dbo.VCT_MAIN_DASHBOARD (no se cambio): ' + ERROR_MESSAGE() + ' (linea ' + CONVERT(VARCHAR(10), ERROR_LINE()) + ')';
        END CATCH;
    END;
END;
GO
